+/**
+ * Canonical arena rules substrate.
+ *
+ * Hosts provide time and transport. This object owns simulation entity identity,
+ * accepted commands, rule-system ordering, stepping, and snapshot resolution.
+ */
+export function createArenaSimulation({ seed, grid, spawns = [] }) {
+  if (!grid) throw new Error('arena simulation requires a collision grid');
+
+  const world = new World({ seed });
+  const playerByPeer = new Map();
+  const networkIdByEntity = new Map();
+  const entityByNetworkId = new Map();
