+
+    const input = world.get(entityId, Input);
+    input.moveX = clampUnit(command.moveX);
+    input.moveY = clampUnit(command.moveY);
+    input.aimX = clampUnit(command.aimX);
+    input.aimY = clampUnit(command.aimY);
