+      if (!world.alive.has(entityId)) continue;
+      entities.push(capturePlayer(peerId, entityId));
+    }
+    entities.sort((a, b) => compareNetworkIds(a.id, b.id));
+    return {
+      version: SIM_SNAPSHOT_VERSION,
+      tick,
+      entities,
+    };
+  }
+
+  /**
