+      let entityId = entityByNetworkId.get(record.id);
+      if (entityId == null || !world.alive.has(entityId)) {
+        entityId = addPlayer(record.owner, 0, record.id);
+      }
+      applyPlayerRecord(entityId, record);
+    }
+
+    for (const [networkId, entityId] of [...entityByNetworkId]) {
+      if (liveNetworkIds.has(networkId)) continue;
+      const peerId = findPeerForEntity(entityId);
+      if (peerId != null) forgetPlayer(peerId, entityId);
+      if (world.alive.has(entityId)) world.destroy(entityId);
+    }
