+    tick = snapshot.tick;
+    lastAppliedSnapshotTick = snapshot.tick;
+    return true;
+  }
+
+  function getPlayerEntity(peerId) {
+    return playerByPeer.get(normalizePeerId(peerId)) ?? null;
+  }
