+  const kind = String(entity.kind || '');
+  if (kind !== 'player') throw new Error(`unsupported simulation entity kind: ${kind || 'missing'}`);
+  const owner = normalizePeerId(entity.owner);
+  const state = entity.state || {};
+  return {
+    id,
+    kind,
+    owner,
+    state: {
+      x: finiteOrZero(state.x),
+      y: finiteOrZero(state.y),
+      vx: finiteOrZero(state.vx),
+      vy: finiteOrZero(state.vy),
+      facing: finiteOrZero(state.facing),
+      hp: finiteOrNull(state.hp),
