+
+function normalizePeerId(peerId) {
+  const id = String(peerId || '').trim();
+  if (!id) throw new Error('player peer id is required');
+  return id;
+}
+
+function normalizeNetworkId(id) {
+  if ((typeof id !== 'number' && typeof id !== 'string') || String(id).length === 0) {
+    throw new Error('simulation entity id must be a number or string');
+  }
+  return id;
+}
+
+function compareNetworkIds(a, b) {
+  return String(a).localeCompare(String(b), 'en', { numeric: true });
+}
+
+function positiveModulo(value, divisor) {
+  const n = Number.isInteger(value) ? value : 0;
+  return ((n % divisor) + divisor) % divisor;
+}
+
+function clampUnit(value) {
+  const n = Number(value);
+  if (!Number.isFinite(n)) return 0;
+  return Math.max(-1, Math.min(1, n));
+}
+
+function finiteOrZero(value) {
+  const n = Number(value);
+  return Number.isFinite(n) ? n : 0;
+}
+
+function finiteOrNull(value) {
+  if (value == null) return null;
+  const n = Number(value);
+  return Number.isFinite(n) ? n : null;
+}
